<?php
 namespace App\Http\Controllers\Auth; use App\Http\Controllers\Controller; use Illuminate\Auth\Events\PasswordReset; use Illuminate\Http\Request; use Illuminate\Http\Response; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Facades\Auth; use Illuminate\Support\Facades\Password; class ResetPasswordController extends Controller { public function reset(Request $request) { $this->validate($request, [ 'token' => 'required', 'email' => 'required|email', 'password' => 'required|confirmed|min:6', ]); $response = Password::broker()->reset( $request->only( 'email', 'password', 'password_confirmation', 'token' ), function ($user, $password) { $this->resetPassword($user, $password); } ); return $response == Password::PASSWORD_RESET ? response([]) : response(['message' => trans($response)], 400); } public function change(Request $request) { $this->validate($request, [ 'old' => 'required|string', 'password' => 'required|string|min:6|max:32|confirmed', ]); $user = Auth::user(); if (!Hash::check($request->post('old'), $user->password)) { return response(['message' => '旧密码错误，请检查'], Response::HTTP_BAD_REQUEST); } $token = $this->resetPassword($user, $request->post('password')); return response([], 200, [ 'Authorization' => 'Bearer ' . $token ]); } public static function resetPassword($user, $password, $login = true) { $user->password = Hash::make($password); $user->setRememberToken(time()); $user->saveOrFail(); event(new PasswordReset($user)); if ($login) return Auth::login($user); else return true; } } 